(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.38)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.5)*8 + Math.cos((x-y)*0.015-t*0.35)*6;
  const w2y = Math.cos((x-y)*0.012+t*0.45)*8 + Math.sin((x+y)*0.018-t*0.4)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*60, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.065, 2.4, 1.12],
    [200+Math.sin(t*0.7+2.5)*90, 220+Math.cos(t*0.3+3.5)*40, 0.095, 1.8, 0.92],
    [300+Math.cos(t*0.42+4.5)*100, 30+Math.sin(t*0.58+1.5)*55, 0.075, 2.2, 1.08]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const fade = 1.0/(1.0+d*0.003);
    aS += Math.sin(d*f-t*sp)*w*fade;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*fade;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*fade*0.5;
  }
  const act=aS/10, inh=iS/10, coup=cS/10;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ripple = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const hessian = (Math.sin(sx*0.22+t*0.7)*Math.sin(sy*0.22-t*0.5)
    + Math.sin(sx*0.17-sy*0.19+t*1.3)*0.6)*0.15;
  const rd = act - inh*0.7 + bg*0.3 + spiral + ripple + coup*0.4;
  const diff = rd*2.2 - Math.sin(rd*3.5+t*0.8)*0.3;
  const reaction = Math.tanh(diff);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = reaction*0.7+cell*0.2+hessian*0.1, v=blend*0.5+0.5;
  const pal = [[6,12,52],[12,45,95],[18,95,125],[25,155,145],[120,195,140],[210,195,75],
    [225,145,55],[195,85,65],[140,40,70],[75,18,55],[30,12,45],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.72?1.18:Math.abs(reaction)>0.5?1.06:1.0;
  const glow=Math.max(0,reaction-0.3)*0.25;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
